insert into public.global_subjects (slug, name, description) values
  ('biology', 'Biology', 'The foundation for health, agriculture, veterinary and life-science careers.'),
  ('chemistry', 'Chemistry', 'Central to health, pharmacy, engineering, agriculture and laboratory careers.'),
  ('agriculture', 'Agriculture', 'Leads to farming, agronomy, extension work and agribusiness.'),
  ('entrepreneurship', 'Entrepreneurship', 'Useful for business, marketing and starting your own enterprise.'),
  ('geography', 'Geography', 'Useful for environment, planning, logistics, tourism and public health.'),
  ('mathematics', 'Mathematics', 'The most widely required subject: engineering, technology, finance, science and many trades build on it.'),
  ('economics', 'Economics', 'Supports business, finance, policy and data careers.'),
  ('accounting', 'Accounting', 'A direct start for accounting, auditing and finance.'),
  ('english', 'English', 'Communication underpins every career; essential for law, media, teaching and business.'),
  ('history', 'History', 'Builds research and argument for law, policy, journalism and teaching.'),
  ('physics', 'Physics', 'Opens engineering, aviation, technology and the physical sciences.'),
  ('woodwork', 'Woodwork', 'Hands-on preparation for carpentry and construction trades.'),
  ('technical-drawing', 'Technical Drawing', 'Supports architecture, engineering, carpentry and construction.'),
  ('metalwork', 'Metalwork', 'Hands-on preparation for welding, fabrication and mechanical trades.'),
  ('fine-art', 'Fine Art', 'Leads to design, architecture, media and creative industries.'),
  ('literature-in-english', 'Literature in English', 'Builds reading, argument and writing for law, media and teaching.'),
  ('foods-and-nutrition', 'Foods and Nutrition', 'Leads to cooking, catering and hospitality careers.'),
  ('foreign-language', 'Foreign Language', 'Valuable in tourism, diplomacy and international business.'),
  ('divinity', 'Divinity', 'Supports social work, counselling, teaching and community roles.'),
  ('computer-studies', 'Computer Studies', 'A head start for software, networks, IT support and data careers.');
