insert into public.data_sources (slug, name, publisher, url, licence, licence_url, access_method, update_frequency, status, attribution, notes) values
  ('world-bank-join', 'Global Jobs Indicators Database (JOIN)', 'World Bank', 'https://databank.worldbank.org/source/global-jobs-indicators-database-(join)', 'World Bank open data terms (generally CC BY 4.0); confirm in the World Bank Data Catalog entry', 'https://www.worldbank.org/en/about/legal/terms-of-use-for-datasets', 'rest_api', 'irregular', 'planned', 'Source: World Bank, Global Jobs Indicators Database (JOIN).', 'API source=86 (api.worldbank.org/v2). 746 series incl. employment by ISCO major group x sex, education, age, urban/rural, and wages. Last updated 2023-05-22.'),
  ('ilostat', 'ILOSTAT', 'International Labour Organization', 'https://ilostat.ilo.org/data/', 'To confirm on ILOSTAT terms of use (expected CC BY 4.0)', null, 'sdmx_api', 'quarterly', 'planned', 'Source: ILOSTAT, International Labour Organization.', 'Employment, earnings and hours by ISCO-08 occupation, sex, age, economic activity for most countries. SDMX API and bulk download; endpoints blocked this research environment, so confirm access from a normal network.'),
  ('oecd-data-explorer', 'OECD Data Explorer (incl. OECD Employment Database)', 'OECD', 'https://www.oecd.org/en/data/datasets/oecd-employment-database.html', 'OECD terms (CC BY 4.0 for most datasets); confirm per dataset', 'https://www.oecd.org/en/about/terms-conditions.html', 'sdmx_api', 'annual', 'planned', 'Source: OECD Data Explorer.', 'SDMX endpoint sdmx.oecd.org/public/rest (1,551 dataflows, 135 labour-related on 2026-11-10), incl. Africa''s Development Dynamics employment by occupation, earnings by field of study, education and earnings.'),
  ('isco-08', 'International Standard Classification of Occupations (ISCO-08)', 'International Labour Organization', 'https://ilostat.ilo.org/methods/concepts-and-definitions/classification-occupation/', 'ILO classification; free to use with attribution (confirm ILO copyright terms)', null, 'bulk_download', 'irregular', 'planned', 'International Standard Classification of Occupations, ISCO-08, International Labour Organization.', 'Imported via ESCO, which publishes the full ISCO-08 hierarchy with ILO group definitions. The ILO download links redirect to ILOSTAT, which blocked automated access.'),
  ('esco', 'ESCO: European Skills, Competences, Qualifications and Occupations', 'European Commission', 'https://esco.ec.europa.eu/', 'Reuse for any purpose, free of charge, provided the source is acknowledged (Commission Decision 2011/833/EU); confirmed in the ESCO FAQ', 'https://esco.ec.europa.eu/en/about-esco/faq', 'rest_api', 'irregular', 'planned', 'Contains ESCO data. (c) European Union.', 'Imported via the ESCO Web Services API (ec.europa.eu/esco/api): the ISCO-08 hierarchy with definitions and ESCO occupations with descriptions, alternative titles and essential skills. Bulk CSV download requires an email form.'),
  ('onet', 'O*NET Database', 'US Department of Labor, Employment and Training Administration', 'https://www.onetcenter.org/database.html', 'CC BY 4.0 (confirmed in the O*NET Resource Center page metadata)', 'https://www.onetcenter.org/license_db.html', 'bulk_download', 'quarterly', 'planned', 'This page includes information from the O*NET 31.0 Database by the U.S. Department of Labor, Employment and Training Administration (USDOL/ETA). Used under the CC BY 4.0 license. Career Proof has modified all or some of this information.', 'Imported O*NET 31.0 (August 2026) text database, db_31_0_text.zip (13.2 MB), plus the official ESCO_to_ONET-SOC crosswalk. Tasks, skills, education, Job Zones and RIASEC interests.'),
  ('unesco-uis', 'UNESCO Institute for Statistics data', 'UNESCO Institute for Statistics', 'https://uis.unesco.org/', 'To confirm on UIS terms', null, 'rest_api', 'annual', 'planned', 'Source: UNESCO Institute for Statistics.', 'Education participation and attainment by country, coded with ISCED 2011 levels.'),
  ('globaljobs-org', 'Global Jobs', 'Global Jobs (globaljobs.org)', 'https://www.globaljobs.org/', 'No reuse rights granted publicly; requires written permission', null, 'partner_feed', 'daily', 'planned', 'Listing via Global Jobs.', 'International affairs, development and policy vacancies. Has an RSS feed and paid employer posting. Approach for a content partnership; do not scrape or republish without agreement.'),
  ('internationaljobs-com', 'InternationalJobs.com', 'AboutJobs.com, Inc.', 'https://www.internationaljobs.com/', 'Copyright AboutJobs.com, Inc.; requires written permission', null, 'partner_feed', 'daily', 'planned', 'Listing via InternationalJobs.com.', 'Overseas and international vacancies; no public API or feed found. Partnership only.'),
  ('careerplanner-com', 'CareerPlanner.com list of careers', 'CareerPlanner.com', 'https://www.careerplanner.com/ListOfCareers.cfm', 'Not stated; treat as copyrighted', null, 'manual', 'irregular', 'retired', 'Reference only.', 'Used only as a benchmark for breadth (about 1,388 careers listed). Not imported: we use the underlying public sources (O*NET, ESCO, ISCO-08) instead.'),
  ('bls-oews', 'Occupational Employment and Wage Statistics (OEWS)', 'U.S. Bureau of Labor Statistics', 'https://www.bls.gov/oes/', 'Public domain (U.S. government work)', 'https://www.bls.gov/opub/copyright-information.htm', 'rest_api', 'annual', 'active', 'Source: U.S. Bureau of Labor Statistics, Occupational Employment and Wage Statistics.', 'Imported 2025 OEWS national estimates via the BLS Public Data API v2 (registered key, stored in git-ignored .env.local): median annual pay and employment for 818 of 867 O*NET occupations (49 have no OEWS series at that code). The bls.gov website blocks automated access, so OOH pages are not crawled.'),
  ('afriqan', 'AfriQAN membership list', 'Association of African Universities (AfriQAN)', 'https://afriqan.aau.org/membership/membership-list/', 'All rights reserved (AAU); names of public bodies used as facts with citation', null, 'manual', 'irregular', 'active', 'As listed by the African Quality Assurance Network (AfriQAN), Association of African Universities.', '27 members; only national/regional regulators kept (14). Membership is not accreditation. Verify each body on its official site.'),
  ('ror', 'Research Organization Registry (ROR)', 'ROR (California Digital Library, Crossref, DataCite)', 'https://ror.org/', 'CC0 1.0 (public domain dedication)', 'https://ror.org/about/faqs/', 'bulk_download', 'monthly', 'active', 'Institution data from the Research Organization Registry (ROR), CC0.', 'Imported ROR data dump v2.15 (2026-10-20, DOI 10.5281/zenodo.23500708, 39.3 MB, MD5 verified): 30,326 active education institutions in 223 countries. Replaces univ.cc. Monthly releases on Zenodo.'),
  ('whed-iau', 'World Higher Education Database (WHED)', 'International Association of Universities (IAU) with UNESCO', 'https://www.whed.net/', 'Not open; www.whed.net robots.txt disallows AI crawlers (ClaudeBot, GPTBot, CCBot) and sets ai-train=no, use=reference', null, 'partner_feed', 'irregular', 'planned', 'World Higher Education Database, IAU/UNESCO.', 'Authoritative list of recognised higher education institutions and credentials in about 200 countries. Not crawled. Request a data licence or partnership from IAU. UNESCO SDG4 knowledge hub page points to WHED.'),
  ('degreeatlas', 'DegreeAtlas institutions', 'degreeatlas.org', 'https://degreeatlas.org/institutions/', 'robots.txt disallows AI crawlers; ai-train=no, use=reference', null, 'manual', 'irregular', 'retired', 'Reference only.', 'Not crawled. Covered by ROR and WHED.'),
  ('au-education', 'African Union, Education directorate', 'African Union Commission', 'https://au.int/en/directorates/education', 'robots.txt disallows AI crawlers; ai-train=no, use=reference', null, 'manual', 'irregular', 'retired', 'Reference only.', 'Policy context (CESA, continental qualifications framework). Not crawled; cite manually where relevant.'),
  ('studymalaysia', 'StudyMalaysia occupation search', 'StudyMalaysia.com', 'https://studymalaysia.com/education/career-guide/occupation-search', 'robots.txt disallows AI crawlers; ai-train=no, use=reference', null, 'partner_feed', 'irregular', 'retired', 'Reference only.', 'Not crawled. Malaysia overlay to come from MASCO (national classification) and official sources or a partnership.'),
  ('world-certification-institute', 'World Certification Institute accredited organisations', 'World Certification Institute (WCI)', 'https://www.worldcertification.org/association/accredited-organizations/', 'All rights reserved (WCI)', null, 'manual', 'irregular', 'retired', 'Not used.', 'Private credentialing body, not a government-recognised accreditor. Excluded so students are not misled about recognition.'),
  ('univ-cc', 'univ.cc Universities Worldwide', 'Klaus Foerster (openweb.cc)', 'https://univ.cc/world', 'Not stated', null, 'manual', 'irregular', 'retired', 'Not used.', 'Private directory of about 7,900 institutions. Superseded by ROR (CC0).'),
  ('planitplus', 'Planit job profiles', 'planitplus.net (Scotland)', 'https://www.planitplus.net/JobProfiles?letter=A', 'Not stated on the page; profiles are written content', null, 'partner_feed', 'irregular', 'retired', 'Reference only.', 'robots.txt allows crawling, but profile text is not reused. ESCO/O*NET cover occupations; a UK overlay can use official UK sources.'),
  ('uganda-moes', 'Ministry of Education and Sports, Uganda', 'Government of Uganda', 'https://www.education.go.ug/', 'All rights reserved', null, 'manual', 'irregular', 'planned', 'Source: Ministry of Education and Sports, Uganda.', 'Links to the authoritative bodies: UNEB (exams), UVTAB (TVET), NCHE (higher education), JAB admissions, scholarships notices. Uganda overlay should cite those bodies directly.'),
  ('certification-issuers', 'Official certification issuer pages', 'ACCA, CFA Institute, PMI, ISC2, CompTIA, Cisco, AWS, Microsoft, SHRM, CIPD, Google', 'https://www.accaglobal.com/', 'Facts only (not reproducing text); each issuer page linked per certification', null, 'manual', 'irregular', 'active', 'Facts as stated on each issuer''s official page, linked and dated.', '11 certifications checked on 2026-11-10 (packages/reference-data/src/certifications.json). PMI read in a normal browser session; one page only. Pending: CIMA, CPA boards, CIPS (blocked), PRINCE2 (page moved), CEH.'),
  ('unesco-recognition', 'UNESCO Global Convention on Higher Education', 'UNESCO', 'https://www.unesco.org/en/higher-education/global-convention', 'Facts cited; UNESCO robots.txt allows ai-input for single pages, disallows AI crawling', null, 'manual', 'irregular', 'active', 'Source: UNESCO.', 'Adopted Nov 2019, in force 5 March 2023, 42 States Parties as of July 2026. Single page read, no crawling.'),
  ('isced-2011', 'ISCED 2011 (International Standard Classification of Education)', 'UNESCO Institute for Statistics (with OECD, Eurostat)', 'https://uis.unesco.org/sites/default/files/documents/isced-2011-operational-manual-guidelines-for-classifying-national-education-programmes-and-related-qualifications-2015-en_1.pdf', 'Classification facts cited', null, 'manual', 'irregular', 'active', 'ISCED 2011, UNESCO Institute for Statistics.', 'Levels 0 to 8; tertiary = 5 to 8. Used on /admissions.'),
  ('cert-articles', 'Certification list articles (IBT Careers, Indeed Career Guide)', 'ibtcareers.com, indeed.com', 'https://www.indeed.com/career-advice/career-development/accredited-certifications', 'Copyrighted articles', null, 'manual', 'irregular', 'retired', 'Not reproduced.', 'Used only to choose which certifications to cover; no text or facts taken.'),
  ('career-programmes-prospects', 'Career programme organisations (Global Career Accelerator, Global Career Path US, Global Career Path Vietnam)', 'Podium Education; Global Career Path; Global Career Path (careerpathways.edu.vn)', 'https://globalcareeraccelerator.org/', 'All rights reserved; no data published', null, 'partner_feed', 'irregular', 'planned', 'Not used.', 'No structured data. Global Career Accelerator: US for-credit programme at 100+ universities. globalcareerpath.com: US/China executive search. careerpathways.edu.vn: Vietnam career guidance consultancy. Partnership prospects only.'),
  ('ucas-tariff', 'UCAS Tariff tables (2027 entry cycle)', 'UCAS', 'https://www.ucas.com/applying/before-you-apply/what-and-where-to-study/entry-requirements/ucas-tariff-points', 'Published reference tables; points values used as facts, attributed to UCAS', null, 'bulk_download', 'annual', 'active', 'Source: UCAS, Tariff tables (2027 entry).', 'Workbook tariff-may-2027_cycle-v1.1.4.1.xlsx; built by scripts/ingest/ucas_tariff_build.py. Supersedes the 2014 proposal PDF, whose IB values differ.'),
  ('admission-bodies', 'National admission bodies (explainers)', 'UAC (Australia), NTA (India); Parcoursup and EducationUSA pending', 'https://www.uac.edu.au/future-applicants/atar', 'Facts only, short attributed statements', null, 'manual', 'annual', 'active', 'Source: each named admission body.', 'ibo.org, parcoursup.gouv.fr and enseignementsup-recherche.gouv.fr block automated access (bot verification); not bypassed. To confirm directly with the bodies.'),
  ('ug-notes-to-schools', 'Notes to Schools 2026/2027 (weighting system, programme requirements, 3-year cut-offs)', 'Ministry of Education & Sports, Uganda (published by Makerere University)', 'https://news.mak.ac.ug/wp-content/uploads/2025/10/Notes-to-Schools-2026-2027-Academic-Year.pdf', 'Public government document; facts reused with attribution', null, 'bulk_download', 'annual', 'active', 'Source: Ministry of Education & Sports, Notes to Schools 2026/2027.', 'Parsed by scripts/ingest/ug_cutoffs_build.py; programme requirements hand-transcribed in ug-programme-requirements.json.'),
  ('makerere-cutoffs', 'Makerere University admission cut-off points (government and private, 2025/2026)', 'Makerere University, Academic Registrar', 'https://www.mak.ac.ug/study-mak/cut-points', 'Public notices; facts reused with attribution', null, 'bulk_download', 'annual', 'active', 'Source: Makerere University Academic Registrar.', 'PDF lists parsed with pdftotext -raw; values cross-checked against the Notes to Schools.'),
  ('nche-uganda', 'NCHE registered institutions and accredited programmes', 'National Council for Higher Education, Uganda', 'https://unche.or.ug/all-academic-programs/', 'Public register; facts reused with attribution', null, 'bulk_download', 'monthly', 'active', 'Source: National Council for Higher Education (NCHE), Uganda.', 'robots.txt allows; data embedded in the page. Parsed by scripts/ingest/nche_build.py.');
